class Hotel {
    private final String name;
    private int reviews;

    Hotel(String name) { this.name = name; }

    void addReview() { reviews++; }

    static class Stats {                  // no outer object required
        private int hotels;
        private int reviews;

        void record(Hotel h) {
            hotels++;
            reviews += h.reviews;         // the outer object arrives as a parameter
        }

        @Override
        public String toString() {
            return hotels + " hotels, " + reviews + " reviews";
        }
    }
}

Hotel.Stats stats = new Hotel.Stats();   // no Hotel before the dot
Hotel a = new Hotel("Danube View");
a.addReview();
stats.record(a);
System.out.println(stats);               // 1 hotels, 1 reviews

class Hotel {
    private final String name;
    private int reviews;

    Hotel(String name) { this.name = name; }

    class Review {                        // inner: this Review belongs to this Hotel
        private final String text;

        Review(String text) { this.text = text; }

        String describe() {
            return name + " (" + reviews + " reviews): " + text;   // outer fields, no getter
        }
    }

    Review review(String text) {
        reviews++;
        return new Review(text);
    }
}

